// Pull the agent's text output, locate the fenced JSON block, parse it.
const raw = $input.first().json.output || $input.first().json.text || '';

function extractFencedJson(text) {
  const fenced = text.match(/```json\s*([\s\S]+?)```/);
  if (fenced) return fenced[1].trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) return text.slice(start, end + 1);
  return null;
}

const jsonText = extractFencedJson(raw);
if (!jsonText) {
  throw new Error('Could not find a JSON block in the agent output. First 400 chars: ' + raw.slice(0, 400));
}

let parsed;
try {
  parsed = JSON.parse(jsonText);
} catch (err) {
  throw new Error('Agent output JSON failed to parse: ' + err.message);
}
if (!parsed.data) throw new Error('Agent output missing required data field.');

return [{
  json: {
    data: parsed.data,
    report_md: parsed.report_md || '',
    summary: parsed.summary || '',
    data_pretty: JSON.stringify(parsed.data, null, 2),
  },
}];
